# O(1) Dictionary Hash Lookup vs O(n) Linear Array Scan:
var card_registry: Dictionary = {} # Key: String ("7♥") -> Value: CardData

func build_index(deck: Array[CardData]) -> void:
    card_registry.clear()
    for c in deck:
        card_registry[c.display_name] = c

func find_card_fast(code: String) -> CardData:
    # O(1) constant-time hash lookup:
    return card_registry.get(code, null)

# LIFO Undo / Redo Stack for Kadi Practice Mode:
class_name UndoHistory
extends RefCounted

var undo_stack: Array[Dictionary] = []
var redo_stack: Array[Dictionary] = []

func record_snapshot(snapshot: Dictionary) -> void:
    undo_stack.push_back(snapshot.duplicate(true))
    redo_stack.clear() # New branch invalidates redo history!

func pop_undo(current_state: Dictionary) -> Dictionary:
    if undo_stack.is_empty():
        return current_state
    redo_stack.push_back(current_state.duplicate(true))
    return undo_stack.pop_back()

