# Sorting Player 0's Kadi Hand by Suit then Rank:
static func sort_hand(hand: Array[CardData]) -> void:
    hand.sort_custom(func(a: CardData, b: CardData) -> bool:
        if a.suit != b.suit:
            return int(a.suit) < int(b.suit)
        return a.rank < b.rank
    )

# O(log n) Binary Search on a Sorted XP Threshold Table:
const LEVEL_XP: Array[int] = [0, 100, 250, 500, 1000, 2000, 4000]

static func get_level_for_xp(xp: int) -> int:
    return LEVEL_XP.bsearch(xp, false)

